#!/usr/bin/env bash
# @lat: [[mobile-expo-config#The Expo config file and the mobile type check#Why native handover happens in an effect, not at module scope]]

set -eu

cd "$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)"

if [ ! -d ios ]; then
    echo "xcode-node-env: no ios/ directory — run 'pnpm prebuild' first." >&2
    exit 0
fi

cat >ios/.xcode.env.local <<'SH'
# Generated by mobile/scripts/xcode-node-env.sh.
# Never pin a version here: the build dies when that version is removed.
if [ -x "$HOME/.local/share/mise/shims/node" ]; then
    export NODE_BINARY="$HOME/.local/share/mise/shims/node"
else
    export NODE_BINARY="$(command -v node)"
fi
SH

echo "xcode-node-env: wrote ios/.xcode.env.local with a version-independent lookup."
